1	import {
2	  type Dispatch,
3	  type RefObject,
4	  type SetStateAction,
5	  useCallback,
6	  useEffect,
7	  useRef,
8	  useState,
9	} from "react";
10	import { toast } from "sonner";
11	import {
12	  archiveItem,
13	  deleteItem,
14	  getProcessingSummaries,
15	  initializeStorage,
16	  listArchivedItems,
17	  type ProcessingSummary,
18	} from "../../lib/libraryApi";
19	import { shouldUseSeedLibrary } from "../../lib/previewMode";
20	import type { LibraryItem } from "../../lib/types";
21	import { storedItemToLibraryItem } from "../library/libraryItem";
22	import { browserArchivedItems } from "../library/seed";
23	
24	// One accepted archive delete: the timer waiting out the undo window, plus the
25	// item that timer needs to restore or reconcile if the delete does not land.
26	type PendingPermanentDelete = {
27	  timer: number;
28	  item: LibraryItem;
29	};
30	
31	type ArchiveOptions = {
32	  canUseDesktopBackend: boolean;
33	  isSettingsOpen: boolean;
34	  isArchiveTabOpen: boolean;
35	  setItems: Dispatch<SetStateAction<LibraryItem[]>>;
36	  itemsRef: RefObject<LibraryItem[]>;
37	  noteBodyCacheRef: RefObject<Map<string, string>>;
38	  selectedItem: LibraryItem | null;
39	  setSelectedItem: Dispatch<SetStateAction<LibraryItem | null>>;
40	  setCaptureError: Dispatch<SetStateAction<string | null>>;
41	};
42	
43	export function useArchive({
44	  canUseDesktopBackend,
45	  isSettingsOpen,
46	  isArchiveTabOpen,
47	  setItems,
48	  itemsRef,
49	  noteBodyCacheRef,
50	  selectedItem,
51	  setSelectedItem,
52	  setCaptureError,
53	}: ArchiveOptions) {
54	  const [archivedItems, setArchivedItems] = useState<LibraryItem[]>(
55	    shouldUseSeedLibrary() ? browserArchivedItems : [],
56	  );
57	  // The archive is read only while its tab is open, so until that read lands
58	  // the list is unknown and Settings must not show a count or an empty state.
59	  const [isArchiveLoaded, setIsArchiveLoaded] = useState(shouldUseSeedLibrary);
60	  const [isArchiveSelectionMode, setIsArchiveSelectionMode] = useState(false);
61	  const [selectedArchivedIds, setSelectedArchivedIds] = useState<Set<string>>(() => new Set());
62	  const pendingPermanentDeletesRef = useRef<Map<string, PendingPermanentDelete>>(new Map());
63	
64	  const cancelPermanentDelete = useCallback((pending: PendingPermanentDelete) => {
65	    const id = String(pending.item.id);
66	    // Only the toast that scheduled a deletion may cancel it. Deleting the same
67	    // item again stores a new record, and that older Undo has to stay a no-op.
68	    if (pendingPermanentDeletesRef.current.get(id) !== pending) return false;
69	    window.clearTimeout(pending.timer);
70	    pendingPermanentDeletesRef.current.delete(id);
71	    return true;
72	  }, []);
73	
74	  const restoreForgottenItem = useCallback(
75	    async (item: LibraryItem) => {
76	      // A restore un-archives the row, so any scheduled permanent delete for it
77	      // must be cancelled or its timer would still fire and destroy the assets.
78	      const pending = pendingPermanentDeletesRef.current.get(String(item.id));
79	      if (pending !== undefined) cancelPermanentDelete(pending);
80	      try {
81	        const restoredItem = canUseDesktopBackend
82	          ? await archiveItem(String(item.id), false).then(async (storedItem) => {
83	              const summary = (await getProcessingSummaries([storedItem.id])).get(storedItem.id);
84	              return storedItemToLibraryItem(storedItem, summary);
85	            })
86	          : { ...item, archived: false };
87	        const cachedNoteBody = noteBodyCacheRef.current.get(String(item.id));
88	        // The restore response carries the description the backend already
89	        // projected; the cache only holds a body this session edited, so it
90	        // re-attaches the body without re-deriving the description.
91	        const restoredLibraryItem =
92	          cachedNoteBody === undefined
93	            ? restoredItem
94	            : { ...restoredItem, noteBody: cachedNoteBody };
95	        setItems((current) =>
96	          current.some((currentItem) => String(currentItem.id) === String(item.id))
97	            ? current
98	            : [restoredLibraryItem, ...current],
99	        );
100	        setArchivedItems((current) =>
101	          current.filter((currentItem) => String(currentItem.id) !== String(item.id)),
102	        );
103	      } catch (error) {
104	        toast.error("Unable to restore this item", { duration: Infinity, closeButton: true });
105	        setCaptureError(error instanceof Error ? error.message : String(error));
106	      }
107	    },
108	    [canUseDesktopBackend, cancelPermanentDelete, setCaptureError, setItems, noteBodyCacheRef],
109	  );
110	
111	  const forgetItem = useCallback(
112	    async (item: LibraryItem) => {
113	      setCaptureError(null);
114	      try {
115	        if (canUseDesktopBackend) {
116	          await archiveItem(String(item.id));
117	        } else {
118	          setArchivedItems((current) =>
119	            current.some((currentItem) => String(currentItem.id) === String(item.id))
120	              ? current
121	              : [{ ...item, archived: true }, ...current],
122	          );
123	        }
124	        setItems((current) =>
125	          current.filter((currentItem) => String(currentItem.id) !== String(item.id)),
126	        );
127	        setSelectedItem(null);
128	
129	        const toastId = `forgot-${String(item.id)}-${Date.now()}`;
130	        toast("Forgotten from your library", {
131	          id: toastId,
132	          description: item.title,
133	          duration: Infinity,
134	          closeButton: true,
135	          className: "library-toast",
136	          action: {
137	            label: "Undo",
138	            onClick: () => void restoreForgottenItem(item),
139	          },
140	        });
141	      } catch (error) {
142	        setCaptureError(error instanceof Error ? error.message : String(error));
143	      }
144	    },
145	    [canUseDesktopBackend, restoreForgottenItem, setItems, setSelectedItem, setCaptureError],
146	  );
147	
148	  // Only the Archive tab reads the archive. Its cards show no processing state,
149	  // and an item opened from here fetches its own summary, so none are read here.
150	  useEffect(() => {
151	    if (!isArchiveTabOpen || shouldUseSeedLibrary()) return;
152	    let cancelled = false;
153	
154	    async function loadArchivedItems() {
155	      try {
156	        await initializeStorage();
157	        const storedItems = await listArchivedItems();
158	        const nextItems = await Promise.all(
159	          storedItems.map((item) => storedItemToLibraryItem(item)),
160	        );
161	        if (!cancelled) {
162	          setArchivedItems(
163	            nextItems.map((item) => {
164	              const noteBody = noteBodyCacheRef.current.get(String(item.id));
165	              return noteBody === undefined ? item : { ...item, noteBody };
166	            }),
167	          );
168	          setIsArchiveLoaded(true);
169	        }
170	      } catch (error) {
171	        if (!cancelled) setCaptureError(error instanceof Error ? error.message : String(error));
172	      }
173	    }
174	
175	    void loadArchivedItems();
176	    return () => {
177	      cancelled = true;
178	    };
179	  }, [isArchiveTabOpen, noteBodyCacheRef, setCaptureError]);
180	
181	  // Each Settings session starts with the archive unread, so a list left from an
182	  // earlier session, including one an import read while Settings was closed, is
183	  // never shown as current.
184	  const [wasSettingsOpen, setWasSettingsOpen] = useState(isSettingsOpen);
185	  if (wasSettingsOpen !== isSettingsOpen) {
186	    setWasSettingsOpen(isSettingsOpen);
187	    if (isSettingsOpen) {
188	      setIsArchiveLoaded(shouldUseSeedLibrary());
189	    } else {
190	      setIsArchiveSelectionMode(false);
191	      setSelectedArchivedIds(new Set());
192	    }
193	  }
194	
195	  const [prunedForItems, setPrunedForItems] = useState(archivedItems);
196	  if (prunedForItems !== archivedItems) {
197	    setPrunedForItems(archivedItems);
198	    const archivedIds = new Set(archivedItems.map((item) => String(item.id)));
199	    setSelectedArchivedIds((current) => {
200	      const next = new Set(Array.from(current).filter((id) => archivedIds.has(id)));
201	      return next.size === current.size ? current : next;
202	    });
203	  }
204	
205	  const restoreArchivedItems = useCallback((restoredItems: LibraryItem[]) => {
206	    if (restoredItems.length === 0) return;
207	    // A settings reload can re-add a row that is still stored, so restore by
208	    // presence instead of blind prepending a second copy of the same item.
209	    setArchivedItems((current) => {
210	      const absent = restoredItems.filter(
211	        (item) => !current.some((candidate) => String(candidate.id) === String(item.id)),
212	      );
213	      return absent.length === 0 ? current : [...absent, ...current];
214	    });
215	  }, []);
216	
217	  const schedulePermanentDelete = useCallback(
218	    (item: LibraryItem) => {
219	      const id = String(item.id);
220	      const previous = pendingPermanentDeletesRef.current.get(id);
221	      if (previous !== undefined) window.clearTimeout(previous.timer);
222	      const pending: PendingPermanentDelete = { timer: 0, item };
223	      pending.timer = window.setTimeout(() => {
224	        pendingPermanentDeletesRef.current.delete(id);
225	        if (!canUseDesktopBackend) return;
226	        void deleteItem(id)
227	          .then(() => {
228	            // The row is still in the database during the undo window, so a reload
229	            // can bring the card back; drop it again now the delete has landed.
230	            setArchivedItems((current) =>
231	              current.filter((candidate) => String(candidate.id) !== id),
232	            );
233	          })
234	          .catch((error) => {
235	            // A recovered item is no longer archived, so its delete fails on
236	            // purpose: leaving it out is already the desired end state and the error
237	            // would only confuse. An item that is still archived comes back here.
238	            if (itemsRef.current.some((candidate) => String(candidate.id) === id)) return;
239	            restoreArchivedItems([item]);
240	            setCaptureError(error instanceof Error ? error.message : String(error));
241	          });
242	      }, 10000);
243	      pendingPermanentDeletesRef.current.set(id, pending);
244	      return pending;
245	    },
246	    [canUseDesktopBackend, restoreArchivedItems, itemsRef, setCaptureError],
247	  );
248	
249	  const undoPermanentDelete = useCallback(
250	    (pendingDeletes: PendingPermanentDelete[]) => {
251	      const restored = pendingDeletes
252	        .filter((pending) => cancelPermanentDelete(pending))
253	        .map((pending) => pending.item);
254	      restoreArchivedItems(restored);
255	    },
256	    [cancelPermanentDelete, restoreArchivedItems],
257	  );
258	
259	  useEffect(
260	    () => () => {
261	      // Unmount must not flush pending deletes: a StrictMode or HMR remount would
262	      // run real deletes. Dropping the timers leaves those items archived and
263	      // recoverable, and window close never unmounts anyway.
264	      for (const pending of pendingPermanentDeletesRef.current.values()) {
265	        window.clearTimeout(pending.timer);
266	      }
267	      pendingPermanentDeletesRef.current.clear();
268	    },
269	    [],
270	  );
271	
272	  const deleteArchivedLibraryItem = useCallback(
273	    (item: LibraryItem) => {
274	      setCaptureError(null);
275	      const itemId = String(item.id);
276	      const pending = schedulePermanentDelete(item);
277	      setArchivedItems((current) => current.filter((candidate) => String(candidate.id) !== itemId));
278	      if (selectedItem && String(selectedItem.id) === itemId) setSelectedItem(null);
279	      toast("Deleted permanently", {
280	        description: item.title,
281	        duration: 10000,
282	        closeButton: true,
283	        className: "library-toast",
284	        action: { label: "Undo", onClick: () => undoPermanentDelete([pending]) },
285	      });
286	    },
287	    [schedulePermanentDelete, selectedItem, undoPermanentDelete, setSelectedItem, setCaptureError],
288	  );
289	
290	  const toggleArchiveSelectionMode = useCallback(() => {
291	    setIsArchiveSelectionMode((current) => {
292	      if (current) setSelectedArchivedIds(new Set());
293	      return !current;
294	    });
295	  }, []);
296	
297	  const toggleArchivedLibraryItem = useCallback((item: LibraryItem) => {
298	    setSelectedArchivedIds((current) => {
299	      const next = new Set(current);
300	      const id = String(item.id);
301	      if (next.has(id)) next.delete(id);
302	      else next.add(id);
303	      return next;
304	    });
305	  }, []);
306	
307	  const isArchivedLibraryItemSelected = useCallback(
308	    (item: LibraryItem) => selectedArchivedIds.has(String(item.id)),
309	    [selectedArchivedIds],
310	  );
311	
312	  const restoreArchivedLibraryItems = useCallback(
313	    async (itemsToRestore: LibraryItem[]) => {
314	      if (itemsToRestore.length === 0) return;
315	      setCaptureError(null);
316	      try {
317	        // Restore every item first, then fetch all processing summaries in one
318	        // batched call instead of one round trip per restored item.
319	        const results = await Promise.allSettled(
320	          itemsToRestore.map(async (item) => {
321	            if (!canUseDesktopBackend) return null;
322	            // A restore un-archives the row, so cancel any scheduled permanent
323	            // delete for it before the timer can fire and destroy its assets.
324	            const pending = pendingPermanentDeletesRef.current.get(String(item.id));
325	            if (pending !== undefined) cancelPermanentDelete(pending);
326	            return archiveItem(String(item.id), false);
327	          }),
328	        );
329	        const restoredStored = results.flatMap((result) =>
330	          result.status === "fulfilled" && result.value ? [result.value] : [],
331	        );
332	        let failures = results.filter((result) => result.status === "rejected").length;
333	        // One batched summaries call for the whole restore. If it fails, the
334	        // items are still restored; only their processing badges fall back.
335	        let summaries = new Map<string, ProcessingSummary>();
336	        try {
337	          if (canUseDesktopBackend && restoredStored.length > 0) {
338	            summaries = await getProcessingSummaries(
339	              restoredStored.map((storedItem) => storedItem.id),
340	            );
341	          }
342	        } catch {
343	          summaries = new Map<string, ProcessingSummary>();
344	        }
345	        // Convert per item so one unreadable item cannot sink the whole batch.
346	        const settled = await Promise.allSettled(
347	          restoredStored.map((storedItem) =>
348	            storedItemToLibraryItem(storedItem, summaries.get(storedItem.id)),
349	          ),
350	        );
351	        failures += settled.filter((result) => result.status === "rejected").length;
352	        const converted = settled.flatMap((result) =>
353	          result.status === "fulfilled" ? [result.value] : [],
354	        );
355	        const restoredItems: LibraryItem[] = [
356	          ...itemsToRestore.filter(() => !canUseDesktopBackend),
357	          ...converted,
358	        ];
359	        const restoredIds = new Set(restoredItems.map((item) => String(item.id)));
360	        setItems((current) => [
361	          ...restoredItems.filter(
362	            (item) => !current.some((candidate) => String(candidate.id) === String(item.id)),
363	          ),
364	          ...current,
365	        ]);
366	        setArchivedItems((current) => current.filter((item) => !restoredIds.has(String(item.id))));
367	        if (restoredItems.length > 0)
368	          toast.success(
369	            `${restoredItems.length} ${restoredItems.length === 1 ? "item" : "items"} restored`,
370	          );
371	        if (failures > 0)
372	          setCaptureError(
373	            `${failures} ${failures === 1 ? "item" : "items"} could not be restored. They are still in the archive.`,
374	          );
375	      } catch (error) {
376	        setCaptureError(error instanceof Error ? error.message : String(error));
377	      }
378	    },
379	    [cancelPermanentDelete, canUseDesktopBackend, setItems, setCaptureError],
380	  );
381	
382	  const restoreSelectedArchivedItems = useCallback(async () => {
383	    const selectedItems = archivedItems.filter((item) => selectedArchivedIds.has(String(item.id)));
384	    await restoreArchivedLibraryItems(selectedItems);
385	    setSelectedArchivedIds(new Set());
386	    setIsArchiveSelectionMode(false);
387	  }, [archivedItems, restoreArchivedLibraryItems, selectedArchivedIds]);
388	
389	  const restoreArchivedLibraryItem = useCallback(
390	    (item: LibraryItem) => restoreArchivedLibraryItems([item]),
391	    [restoreArchivedLibraryItems],
392	  );
393	
394	  const deleteSelectedArchivedItems = useCallback(() => {
395	    const selectedItems = archivedItems.filter((item) => selectedArchivedIds.has(String(item.id)));
396	    if (selectedItems.length === 0) return;
397	    setCaptureError(null);
398	    const deletedIds = new Set(selectedItems.map((item) => String(item.id)));
399	    const pendingDeletes = selectedItems.map((item) => schedulePermanentDelete(item));
400	    setArchivedItems((current) => current.filter((item) => !deletedIds.has(String(item.id))));
401	    if (selectedItem && deletedIds.has(String(selectedItem.id))) setSelectedItem(null);
402	    setSelectedArchivedIds(new Set());
403	    setIsArchiveSelectionMode(false);
404	    toast(
405	      `${selectedItems.length} ${selectedItems.length === 1 ? "item" : "items"} deleted permanently`,
406	      {
407	        duration: 10000,
408	        closeButton: true,
409	        className: "library-toast",
410	        action: { label: "Undo", onClick: () => undoPermanentDelete(pendingDeletes) },
411	      },
412	    );
413	  }, [
414	    archivedItems,
415	    schedulePermanentDelete,
416	    selectedArchivedIds,
417	    selectedItem,
418	    undoPermanentDelete,
419	    setSelectedItem,
420	    setCaptureError,
421	  ]);
422	
423	  return {
424	    archivedItems,
