const port = process.argv[2];
const list = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const page = list.find((p) => p.type === "page" && p.url.startsWith("app://"));
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve) => (ws.onopen = resolve));
let nextId = 0;
const pending = new Map();
ws.onmessage = (event) => {
  const message = JSON.parse(event.data);
  if (pending.has(message.id)) {
    pending.get(message.id)(message);
    pending.delete(message.id);
  }
};
const expression = `(() => {
  const button = [...document.querySelectorAll('.nt-root .nt-action')].find((node) => node.textContent.includes('Undo'));
  if (!button) return null;
  const rect = button.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  const dpr = window.devicePixelRatio;
  const top = document.elementFromPoint(cx, cy);
  return {
    x: Math.round((window.screenX + cx) * dpr),
    y: Math.round((window.screenY + cy) * dpr),
    dpr,
    topElement: top ? top.className?.baseVal ?? top.className : null,
    topIsUndo: top === button || button.contains(top),
  };
})()`;
nextId += 1;
const reply = new Promise((resolve) => pending.set(nextId, resolve));
ws.send(JSON.stringify({ id: nextId, method: "Runtime.evaluate", params: { expression, returnByValue: true } }));
const result = await reply;
console.log(JSON.stringify(result.result.result.value));
ws.close();
EOF
