foreach ($pt in $pts) {
  $p = New-Object WinProbe+POINT; $p.X = $pt.x; $p.Y = $pt.y
  $h = [WinProbe]::WindowFromPoint($p)
  $root = [WinProbe]::GetAncestor($h, 2)
  $procId = 0; [WinProbe]::GetWindowThreadProcessId($root, [ref]$procId) | Out-Null
  $proc = Get-Process -Id $procId -ErrorAction SilentlyContinue
  "point $($pt.x),$($pt.y) -> hwnd $root pid $procId ($($proc.ProcessName))"
}
$electron = Get-Process electron -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne 0 }
foreach ($e in $electron) { $r = New-Object WinProbe+RECT; [WinProbe]::GetWindowRect($e.MainWindowHandle, [ref]$r) | Out-Null; "electron pid $($e.Id) hwnd $($e.MainWindowHandle) visible=$([WinProbe]::IsWindowVisible($e.MainWindowHandle)) rect=$($r.Left),$($r.Top),$($r.Right),$($r.Bottom) title='$($e.MainWindowTitle)'" }
"foreground: " + (Get-Process | Where-Object { $_.MainWindowHandle -eq [WinProbe]::GetForegroundWindow() } | ForEach-Object { $_.ProcessName })
Add-Type -AssemblyName System.Windows.Forms; "cursor now: " + [System.Windows.Forms.Cursor]::Position

