1	import {
2	  type Dispatch,
3	  type RefObject,
4	  type SetStateAction,
5	  useCallback,
6	  useEffect,
7	  useRef,
8	  useState,
9	} from "react";
10	import { toast } from "notch-toast";
11	import {
12	  archiveItem,
13	  deleteItem,
14	  getProcessingSummaries,
15	  initializeStorage,
16	  listArchivedItems,
17	  type ProcessingSummary,
18	} from "../../lib/libraryApi";
19	import { shouldUseSeedLibrary } from "../../lib/previewMode";
20	import type { LibraryItem } from "../../lib/types";
21	import { storedItemToLibraryItem } from "../library/libraryItem";
22	import { browserArchivedItems } from "../library/seed";
23	
24	// One accepted archive delete: the timer waiting out the undo window, plus the
25	// item that timer needs to restore or reconcile if the delete does not land.
26	type PendingPermanentDelete = {
27	  timer: number;
28	  item: LibraryItem;
29	};
30	
31	type ArchiveOptions = {
32	  canUseDesktopBackend: boolean;
33	  isSettingsOpen: boolean;
34	  isArchiveTabOpen: boolean;
35	  setItems: Dispatch<SetStateAction<LibraryItem[]>>;
36	  itemsRef: RefObject<LibraryItem[]>;
37	  noteBodyCacheRef: RefObject<Map<string, string>>;
38	  selectedItem: LibraryItem | null;
39	  setSelectedItem: Dispatch<SetStateAction<LibraryItem | null>>;
40	  setCaptureError: Dispatch<SetStateAction<string | null>>;
41	};
42	
43	// notch-toast keeps the island up after its action runs, so Undo closes it here.
44	function undoAction(onUndo: () => void) {
45	  return {
46	    label: "Undo",
47	    onClick: () => {
48	      toast.dismiss();
49	      onUndo();
50	    },
51	  };
52	}
53	
54	export function useArchive({
55	  canUseDesktopBackend,
56	  isSettingsOpen,
57	  isArchiveTabOpen,
58	  setItems,
59	  itemsRef,
60	  noteBodyCacheRef,
61	  selectedItem,
62	  setSelectedItem,
63	  setCaptureError,
64	}: ArchiveOptions) {
65	  const [archivedItems, setArchivedItems] = useState<LibraryItem[]>(
66	    shouldUseSeedLibrary() ? browserArchivedItems : [],
67	  );
68	  // The archive is read only while its tab is open, so until that read lands
69	  // the list is unknown and Settings must not show a count or an empty state.
70	  const [isArchiveLoaded, setIsArchiveLoaded] = useState(shouldUseSeedLibrary);
71	  const [isArchiveSelectionMode, setIsArchiveSelectionMode] = useState(false);
72	  const [selectedArchivedIds, setSelectedArchivedIds] = useState<Set<string>>(() => new Set());
73	  const pendingPermanentDeletesRef = useRef<Map<string, PendingPermanentDelete>>(new Map());
74	
75	  const cancelPermanentDelete = useCallback((pending: PendingPermanentDelete) => {
76	    const id = String(pending.item.id);
77	    // Only the toast that scheduled a deletion may cancel it. Deleting the same
78	    // item again stores a new record, and that older Undo has to stay a no-op.
79	    if (pendingPermanentDeletesRef.current.get(id) !== pending) return false;
80	    window.clearTimeout(pending.timer);
81	    pendingPermanentDeletesRef.current.delete(id);
82	    return true;
83	  }, []);
84	
85	  const restoreForgottenItem = useCallback(
86	    async (item: LibraryItem) => {
87	      // A restore un-archives the row, so any scheduled permanent delete for it
88	      // must be cancelled or its timer would still fire and destroy the assets.
89	      const pending = pendingPermanentDeletesRef.current.get(String(item.id));
90	      if (pending !== undefined) cancelPermanentDelete(pending);
91	      try {
92	        const restoredItem = canUseDesktopBackend
93	          ? await archiveItem(String(item.id), false).then(async (storedItem) => {
94	              const summary = (await getProcessingSummaries([storedItem.id])).get(storedItem.id);
95	              return storedItemToLibraryItem(storedItem, summary);
96	            })
97	          : { ...item, archived: false };
98	        const cachedNoteBody = noteBodyCacheRef.current.get(String(item.id));
99	        // The restore response carries the description the backend already
100	        // projected; the cache only holds a body this session edited, so it
101	        // re-attaches the body without re-deriving the description.
102	        const restoredLibraryItem =
103	          cachedNoteBody === undefined
104	            ? restoredItem
105	            : { ...restoredItem, noteBody: cachedNoteBody };
106	        setItems((current) =>
107	          current.some((currentItem) => String(currentItem.id) === String(item.id))
108	            ? current
109	            : [restoredLibraryItem, ...current],
110	        );
111	        setArchivedItems((current) =>
112	          current.filter((currentItem) => String(currentItem.id) !== String(item.id)),
113	        );
114	      } catch (error) {
115	        toast.error("Unable to restore this item");
116	        setCaptureError(error instanceof Error ? error.message : String(error));
117	      }
118	    },
119	    [canUseDesktopBackend, cancelPermanentDelete, setCaptureError, setItems, noteBodyCacheRef],
120	  );
121	
122	  const forgetItem = useCallback(
123	    async (item: LibraryItem) => {
124	      setCaptureError(null);
125	      try {
126	        if (canUseDesktopBackend) {
127	          await archiveItem(String(item.id));
128	        } else {
129	          setArchivedItems((current) =>
130	            current.some((currentItem) => String(currentItem.id) === String(item.id))
131	              ? current
132	              : [{ ...item, archived: true }, ...current],
133	          );
134	        }
135	        setItems((current) =>
136	          current.filter((currentItem) => String(currentItem.id) !== String(item.id)),
137	        );
138	        setSelectedItem(null);
139	
140	        toast("Forgotten from your library", {
141	          duration: 0,
142	          dismissible: true,
143	          action: undoAction(() => void restoreForgottenItem(item)),
144	        });
145	      } catch (error) {
146	        setCaptureError(error instanceof Error ? error.message : String(error));
147	      }
148	    },
149	    [canUseDesktopBackend, restoreForgottenItem, setItems, setSelectedItem, setCaptureError],
150	  );
151	
152	  // Only the Archive tab reads the archive. Its cards show no processing state,
153	  // and an item opened from here fetches its own summary, so none are read here.
154	  useEffect(() => {
155	    if (!isArchiveTabOpen || shouldUseSeedLibrary()) return;
156	    let cancelled = false;
157	
158	    async function loadArchivedItems() {
159	      try {
160	        await initializeStorage();
161	        const storedItems = await listArchivedItems();
162	        const nextItems = await Promise.all(
163	          storedItems.map((item) => storedItemToLibraryItem(item)),
164	        );
165	        if (!cancelled) {
166	          setArchivedItems(
167	            nextItems.map((item) => {
168	              const noteBody = noteBodyCacheRef.current.get(String(item.id));
169	              return noteBody === undefined ? item : { ...item, noteBody };
170	            }),
171	          );
172	          setIsArchiveLoaded(true);
173	        }
174	      } catch (error) {
175	        if (!cancelled) setCaptureError(error instanceof Error ? error.message : String(error));
176	      }
177	    }
178	
179	    void loadArchivedItems();
180	    return () => {
181	      cancelled = true;
182	    };
183	  }, [isArchiveTabOpen, noteBodyCacheRef, setCaptureError]);
184	
185	  // Each Settings session starts with the archive unread, so a list left from an
186	  // earlier session, including one an import read while Settings was closed, is
187	  // never shown as current.
188	  const [wasSettingsOpen, setWasSettingsOpen] = useState(isSettingsOpen);
189	  if (wasSettingsOpen !== isSettingsOpen) {
190	    setWasSettingsOpen(isSettingsOpen);
191	    if (isSettingsOpen) {
192	      setIsArchiveLoaded(shouldUseSeedLibrary());
193	    } else {
194	      setIsArchiveSelectionMode(false);
195	      setSelectedArchivedIds(new Set());
196	    }
197	  }
198	
199	  const [prunedForItems, setPrunedForItems] = useState(archivedItems);
200	  if (prunedForItems !== archivedItems) {
201	    setPrunedForItems(archivedItems);
202	    const archivedIds = new Set(archivedItems.map((item) => String(item.id)));
203	    setSelectedArchivedIds((current) => {
204	      const next = new Set(Array.from(current).filter((id) => archivedIds.has(id)));
205	      return next.size === current.size ? current : next;
206	    });
207	  }
208	
209	  const restoreArchivedItems = useCallback((restoredItems: LibraryItem[]) => {
210	    if (restoredItems.length === 0) return;
211	    // A settings reload can re-add a row that is still stored, so restore by
212	    // presence instead of blind prepending a second copy of the same item.
213	    setArchivedItems((current) => {
214	      const absent = restoredItems.filter(
215	        (item) => !current.some((candidate) => String(candidate.id) === String(item.id)),
216	      );
217	      return absent.length === 0 ? current : [...absent, ...current];
218	    });
219	  }, []);
220	
221	  const schedulePermanentDelete = useCallback(
222	    (item: LibraryItem) => {
223	      const id = String(item.id);
224	      const previous = pendingPermanentDeletesRef.current.get(id);
225	      if (previous !== undefined) window.clearTimeout(previous.timer);
226	      const pending: PendingPermanentDelete = { timer: 0, item };
227	      pending.timer = window.setTimeout(() => {
228	        pendingPermanentDeletesRef.current.delete(id);
229	        if (!canUseDesktopBackend) return;
230	        void deleteItem(id)
231	          .then(() => {
232	            // The row is still in the database during the undo window, so a reload
233	            // can bring the card back; drop it again now the delete has landed.
234	            setArchivedItems((current) =>
235	              current.filter((candidate) => String(candidate.id) !== id),
236	            );
237	          })
238	          .catch((error) => {
239	            // A recovered item is no longer archived, so its delete fails on
240	            // purpose: leaving it out is already the desired end state and the error
241	            // would only confuse. An item that is still archived comes back here.
242	            if (itemsRef.current.some((candidate) => String(candidate.id) === id)) return;
243	            restoreArchivedItems([item]);
244	            setCaptureError(error instanceof Error ? error.message : String(error));
245	          });
246	      }, 10000);
247	      pendingPermanentDeletesRef.current.set(id, pending);
248	      return pending;
249	    },
250	    [canUseDesktopBackend, restoreArchivedItems, itemsRef, setCaptureError],
251	  );
252	
253	  const undoPermanentDelete = useCallback(
254	    (pendingDeletes: PendingPermanentDelete[]) => {
255	      const restored = pendingDeletes
256	        .filter((pending) => cancelPermanentDelete(pending))
257	        .map((pending) => pending.item);
258	      restoreArchivedItems(restored);
259	    },
260	    [cancelPermanentDelete, restoreArchivedItems],
261	  );
262	
263	  useEffect(
264	    () => () => {
265	      // Unmount must not flush pending deletes: a StrictMode or HMR remount would
266	      // run real deletes. Dropping the timers leaves those items archived and
267	      // recoverable, and window close never unmounts anyway.
268	      for (const pending of pendingPermanentDeletesRef.current.values()) {
269	        window.clearTimeout(pending.timer);
270	      }
271	      pendingPermanentDeletesRef.current.clear();
272	    },
273	    [],
274	  );
275	
276	  const deleteArchivedLibraryItem = useCallback(
277	    (item: LibraryItem) => {
278	      setCaptureError(null);
279	      const itemId = String(item.id);
280	      const pending = schedulePermanentDelete(item);
281	      setArchivedItems((current) => current.filter((candidate) => String(candidate.id) !== itemId));
282	      if (selectedItem && String(selectedItem.id) === itemId) setSelectedItem(null);
283	      toast("Deleted permanently", {
284	        duration: 10000,
285	        dismissible: true,
286	        action: undoAction(() => undoPermanentDelete([pending])),
287	      });
288	    },
289	    [schedulePermanentDelete, selectedItem, undoPermanentDelete, setSelectedItem, setCaptureError],
290	  );
291	
292	  const toggleArchiveSelectionMode = useCallback(() => {
293	    setIsArchiveSelectionMode((current) => {
294	      if (current) setSelectedArchivedIds(new Set());
295	      return !current;
296	    });
297	  }, []);
298	
299	  const toggleArchivedLibraryItem = useCallback((item: LibraryItem) => {
300	    setSelectedArchivedIds((current) => {
301	      const next = new Set(current);
302	      const id = String(item.id);
303	      if (next.has(id)) next.delete(id);
304	      else next.add(id);
305	      return next;
306	    });
307	  }, []);
308	
309	  const isArchivedLibraryItemSelected = useCallback(
310	    (item: LibraryItem) => selectedArchivedIds.has(String(item.id)),
311	    [selectedArchivedIds],
312	  );
313	
314	  const restoreArchivedLibraryItems = useCallback(
315	    async (itemsToRestore: LibraryItem[]) => {
316	      if (itemsToRestore.length === 0) return;
317	      setCaptureError(null);
318	      try {
319	        // Restore every item first, then fetch all processing summaries in one
320	        // batched call instead of one round trip per restored item.
321	        const results = await Promise.allSettled(
322	          itemsToRestore.map(async (item) => {
323	            if (!canUseDesktopBackend) return null;
324	            // A restore un-archives the row, so cancel any scheduled permanent
325	            // delete for it before the timer can fire and destroy its assets.
326	            const pending = pendingPermanentDeletesRef.current.get(String(item.id));
327	            if (pending !== undefined) cancelPermanentDelete(pending);
328	            return archiveItem(String(item.id), false);
329	          }),
330	        );
331	        const restoredStored = results.flatMap((result) =>
332	          result.status === "fulfilled" && result.value ? [result.value] : [],
333	        );
334	        let failures = results.filter((result) => result.status === "rejected").length;
335	        // One batched summaries call for the whole restore. If it fails, the
336	        // items are still restored; only their processing badges fall back.
337	        let summaries = new Map<string, ProcessingSummary>();
338	        try {
339	          if (canUseDesktopBackend && restoredStored.length > 0) {
340	            summaries = await getProcessingSummaries(
341	              restoredStored.map((storedItem) => storedItem.id),
342	            );
343	          }
344	        } catch {
345	          summaries = new Map<string, ProcessingSummary>();
346	        }
347	        // Convert per item so one unreadable item cannot sink the whole batch.
348	        const settled = await Promise.allSettled(
349	          restoredStored.map((storedItem) =>
350	            storedItemToLibraryItem(storedItem, summaries.get(storedItem.id)),
351	          ),
352	        );
353	        failures += settled.filter((result) => result.status === "rejected").length;
354	        const converted = settled.flatMap((result) =>
355	          result.status === "fulfilled" ? [result.value] : [],
356	        );
357	        const restoredItems: LibraryItem[] = [
358	          ...itemsToRestore.filter(() => !canUseDesktopBackend),
359	          ...converted,
360	        ];
361	        const restoredIds = new Set(restoredItems.map((item) => String(item.id)));
362	        setItems((current) => [
363	          ...restoredItems.filter(
364	            (item) => !current.some((candidate) => String(candidate.id) === String(item.id)),
365	          ),
366	          ...current,
367	        ]);
368	        setArchivedItems((current) => current.filter((item) => !restoredIds.has(String(item.id))));
369	        if (restoredItems.length > 0)
370	          toast.success(
371	            `${restoredItems.length} ${restoredItems.length === 1 ? "item" : "items"} restored`,
372	            { duration: 5000 },
373	          );
374	        if (failures > 0)
375	          setCaptureError(
376	            `${failures} ${failures === 1 ? "item" : "items"} could not be restored. They are still in the archive.`,
377	          );
378	      } catch (error) {
379	        setCaptureError(error instanceof Error ? error.message : String(error));
380	      }
381	    },
382	    [cancelPermanentDelete, canUseDesktopBackend, setItems, setCaptureError],
383	  );
384	
385	  const restoreSelectedArchivedItems = useCallback(async () => {
386	    const selectedItems = archivedItems.filter((item) => selectedArchivedIds.has(String(item.id)));
387	    await restoreArchivedLibraryItems(selectedItems);
388	    setSelectedArchivedIds(new Set());
389	    setIsArchiveSelectionMode(false);
390	  }, [archivedItems, restoreArchivedLibraryItems, selectedArchivedIds]);
391	
392	  const restoreArchivedLibraryItem = useCallback(
393	    (item: LibraryItem) => restoreArchivedLibraryItems([item]),
394	    [restoreArchivedLibraryItems],
395	  );
396	
397	  const deleteSelectedArchivedItems = useCallback(() => {
398	    const selectedItems = archivedItems.filter((item) => selectedArchivedIds.has(String(item.id)));
399	    if (selectedItems.length === 0) return;
400	    setCaptureError(null);
401	    const deletedIds = new Set(selectedItems.map((item) => String(item.id)));
402	    const pendingDeletes = selectedItems.map((item) => schedulePermanentDelete(item));
403	    setArchivedItems((current) => current.filter((item) => !deletedIds.has(String(item.id))));
404	    if (selectedItem && deletedIds.has(String(selectedItem.id))) setSelectedItem(null);
405	    setSelectedArchivedIds(new Set());
406	    setIsArchiveSelectionMode(false);
407	    toast(
408	      `${selectedItems.length} ${selectedItems.length === 1 ? "item" : "items"} deleted permanently`,
409	      {
410	        duration: 10000,
411	        dismissible: true,
412	        action: undoAction(() => undoPermanentDelete(pendingDeletes)),
413	      },
414	    );
415	  }, [
416	    archivedItems,
417	    schedulePermanentDelete,
418	    selectedArchivedIds,
419	    selectedItem,
420	    undoPermanentDelete,
421	    setSelectedItem,
422	    setCaptureError,
